                writer.WriteNumber("sequence_group", spellScriptUsage.SequenceGroupOption.Value!.Value);

            if (spellScriptUsage.ActivationMaskOption.IsSet)
            {
                writer.WritePropertyName("activation_mask");
                JsonSerializer.Serialize(writer, spellScriptUsage.ActivationMask, jsonSerializerOptions);
            }
            if (spellScriptUsage.CasterMaskOption.IsSet)
            {
                writer.WritePropertyName("caster_mask");
                JsonSerializer.Serialize(writer, spellScriptUsage.CasterMask, jsonSerializerOptions);
            }
            if (spellScriptUsage.TargetMaskOption.IsSet)
            {
                writer.WritePropertyName("target_mask");
                JsonSerializer.Serialize(writer, spellScriptUsage.TargetMask, jsonSerializerOptions);
            }
            if (spellScriptUsage.ActivationZoneOption.IsSet)
            {
                writer.WritePropertyName("activation_zone");
                JsonSerializer.Serialize(writer, spellScriptUsage.ActivationZone, jsonSerializerOptions);
            }
            if (spellScriptUsage.TargetZoneOption.IsSet)
            {
                writer.WritePropertyName("target_zone");
                JsonSerializer.Serialize(writer, spellScriptUsage.TargetZone, jsonSerializerOptions);
            }
            if (spellScriptUsage.ConditionOption.IsSet)
                if (spellScriptUsage.ConditionOption.Value != null)
                {
                    writer.WritePropertyName("condition");
                    JsonSerializer.Serialize(writer, spellScriptUsage.Condition, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("condition");
            if (spellScriptUsage.TargetsAffectedConcurrentlyOption.IsSet)
                writer.WriteBoolean("targets_affected_concurrently", spellScriptUsage.TargetsAffectedConcurrentlyOption.Value!.Value);

            if (spellScriptUsage.TargetTreatedAsCasterOption.IsSet)
                writer.WriteBoolean("target_treated_as_caster", spellScriptUsage.TargetTreatedAsCasterOption.Value!.Value);

            if (spellScriptUsage.SpellLevelIdsOption.IsSet)
            {
                writer.WritePropertyName("spell_level_ids");
                JsonSerializer.Serialize(writer, spellScriptUsage.SpellLevelIds, jsonSerializerOptions);
            }
        }
    }
